import React, { useState, useEffect } from "react";

const ImageGallerySection = () => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [direction, setDirection] = useState("left");

  const images = [
    {
      src: "/images/storefront_michel_cell.jpg",
      alt: "Michel Cell Storefront",
      caption: "Notre boutique principale",
    },
    {
      src: "/images/store-interior-1.jpg",
      alt: "Intérieur de la boutique",
      caption: "Espace d'exposition moderne",
    },
    {
      src: "/images/our_last_smartphone.jpg",
      alt: "Display de produits",
      caption: "Nos derniers smartphones",
    },
    {
      src: "/images/customer-service.jpg",
      alt: "Service client",
      caption: "Accompagnement personnalisé",
    },
    {
      src: "/images/repair-station.jpg",
      alt: "Station de réparation",
      caption: "Atelier technique expert",
    },
    {
      src: "/images/gaming_space_vr.jpg",
      alt: "Espace gaming",
      caption: "Zone dédiée aux gamers",
    },
    {
      src: "/images/accessories-wall.jpg",
      alt: "Mur d'accessoires",
      caption: "Large choix d'accessoires",
    },
    {
      src: "/images/team-photo.jpg",
      alt: "Équipe Michel Cell",
      caption: "Notre équipe d'experts",
    },
  ];

  const directions = [
    "left",
    "right",
    "top",
    "bottom",
    "top-left",
    "top-right",
    "bottom-left",
    "bottom-right",
    "zoom-in",
    "zoom-out",
    "rotate-left",
    "rotate-right",
  ];

  const getRandomDirection = () => {
    const randomIndex = Math.floor(Math.random() * directions.length);
    return directions[randomIndex];
  };

  useEffect(() => {
    const interval = setInterval(() => {
      const newDirection = getRandomDirection();
      setDirection(newDirection);
      setCurrentImageIndex((prevIndex) => (prevIndex + 1) % images.length);
    }, 4000); // Change toutes les 4 secondes

    return () => clearInterval(interval);
  }, [images.length]);

  const getAnimationClass = (dir) => {
    const baseClass =
      "w-full h-full object-cover transition-all duration-1000 ease-in-out";

    switch (dir) {
      case "left":
        return `${baseClass} animate-slide-in-left`;
      case "right":
        return `${baseClass} animate-slide-in-right`;
      case "top":
        return `${baseClass} animate-slide-in-top`;
      case "bottom":
        return `${baseClass} animate-slide-in-bottom`;
      case "top-left":
        return `${baseClass} animate-slide-in-top-left`;
      case "top-right":
        return `${baseClass} animate-slide-in-top-right`;
      case "bottom-left":
        return `${baseClass} animate-slide-in-bottom-left`;
      case "bottom-right":
        return `${baseClass} animate-slide-in-bottom-right`;
      case "zoom-in":
        return `${baseClass} animate-zoom-in`;
      case "zoom-out":
        return `${baseClass} animate-zoom-out`;
      case "rotate-left":
        return `${baseClass} animate-rotate-left`;
      case "rotate-right":
        return `${baseClass} animate-rotate-right`;
      default:
        return `${baseClass} animate-fade-in`;
    }
  };

  return (
    <section className="relative h-screen w-full overflow-hidden">
      {/* Image de fond pleine page */}
      <div className="absolute inset-0">
        <img
          src={images[currentImageIndex].src}
          alt={images[currentImageIndex].alt}
          className={getAnimationClass(direction)}
        />

        {/* Overlay sombre pour améliorer la lisibilité */}
        <div className="absolute inset-0 bg-black/40"></div>
      </div>

      {/* Contenu superposé */}
      <div className="relative z-10 h-full w-full flex flex-col items-center justify-center px-4">
        {/* Conteneur pour les contrôles et la légende */}
        <div className="max-w-4xl w-full mx-auto">
          {/* Légende */}
          <div className="bg-black/50 backdrop-blur-sm rounded-xl p-6 mb-8 border border-white/20 transform transition-all duration-500 ease-in-out">
            <p className="font-mono text-white text-2xl md:text-3xl text-center">
              {images[currentImageIndex].caption}
            </p>
          </div>

          {/* Navigation Dots */}
          <div className="flex justify-center gap-3 mb-8">
            {images.map((_, index) => (
              <button
                key={index}
                onClick={() => {
                  setCurrentImageIndex(index);
                  setDirection(getRandomDirection());
                }}
                className={`w-4 h-4 rounded-full transition-all duration-300 ${
                  index === currentImageIndex
                    ? "bg-red-500 scale-125"
                    : "bg-white/60 hover:bg-red-400"
                }`}
                aria-label={`Aller à l'image ${index + 1}`}
              />
            ))}
          </div>

          {/* Navigation Arrows */}
          <button
            onClick={() => {
              setCurrentImageIndex(
                (prev) => (prev - 1 + images.length) % images.length,
              );
              setDirection(getRandomDirection());
            }}
            className="absolute left-4 top-1/2 transform -translate-y-1/2 bg-black/30 backdrop-blur-sm hover:bg-black/50 border border-white/30 rounded-full p-4 transition-all duration-300 hover:scale-110 hover:border-red-300 text-white"
            aria-label="Image précédente"
          >
            <svg
              className="w-8 h-8"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M15 19l-7-7 7-7"
              />
            </svg>
          </button>

          <button
            onClick={() => {
              setCurrentImageIndex((prev) => (prev + 1) % images.length);
              setDirection(getRandomDirection());
            }}
            className="absolute right-4 top-1/2 transform -translate-y-1/2 bg-black/30 backdrop-blur-sm hover:bg-black/50 border border-white/30 rounded-full p-4 transition-all duration-300 hover:scale-110 hover:border-red-300 text-white"
            aria-label="Image suivante"
          >
            <svg
              className="w-8 h-8"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5l7 7-7 7"
              />
            </svg>
          </button>

          {/* Progress Bar */}
          <div className="bg-white/20 rounded-full h-2 overflow-hidden max-w-2xl mx-auto">
            <div
              className="bg-red-500 h-full rounded-full transition-all duration-1000 ease-linear"
              style={{
                width: `${((currentImageIndex + 1) / images.length) * 100}%`,
              }}
            />
          </div>

          {/* Image Counter */}
          <div className="text-center mt-4">
            <span className="font-mono text-white text-lg bg-black/30 px-4 py-2 rounded-full">
              {currentImageIndex + 1} / {images.length}
            </span>
          </div>
        </div>
      </div>

      {/* Animation Styles */}
      <style jsx global>{`
        @keyframes slide-in-left {
          from {
            transform: translateX(-100%) scale(1.1);
            opacity: 0;
          }
          to {
            transform: translateX(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-right {
          from {
            transform: translateX(100%) scale(1.1);
            opacity: 0;
          }
          to {
            transform: translateX(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-top {
          from {
            transform: translateY(-100%) scale(1.1);
            opacity: 0;
          }
          to {
            transform: translateY(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-bottom {
          from {
            transform: translateY(100%) scale(1.1);
            opacity: 0;
          }
          to {
            transform: translateY(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-top-left {
          from {
            transform: translate(-100%, -100%) scale(1.2);
            opacity: 0;
          }
          to {
            transform: translate(0, 0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-top-right {
          from {
            transform: translate(100%, -100%) scale(1.2);
            opacity: 0;
          }
          to {
            transform: translate(0, 0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-bottom-left {
          from {
            transform: translate(-100%, 100%) scale(1.2);
            opacity: 0;
          }
          to {
            transform: translate(0, 0) scale(1);
            opacity: 1;
          }
        }

        @keyframes slide-in-bottom-right {
          from {
            transform: translate(100%, 100%) scale(1.2);
            opacity: 0;
          }
          to {
            transform: translate(0, 0) scale(1);
            opacity: 1;
          }
        }

        @keyframes zoom-in {
          from {
            transform: scale(0.8);
            opacity: 0;
          }
          to {
            transform: scale(1);
            opacity: 1;
          }
        }

        @keyframes zoom-out {
          from {
            transform: scale(1.2);
            opacity: 0;
          }
          to {
            transform: scale(1);
            opacity: 1;
          }
        }

        @keyframes rotate-left {
          from {
            transform: rotate(-45deg) scale(1.1);
            opacity: 0;
          }
          to {
            transform: rotate(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes rotate-right {
          from {
            transform: rotate(45deg) scale(1.1);
            opacity: 0;
          }
          to {
            transform: rotate(0) scale(1);
            opacity: 1;
          }
        }

        @keyframes fade-in {
          from {
            opacity: 0;
            transform: scale(1);
          }
          to {
            opacity: 1;
